const output = [];

for (const item of $input.all()) {
  const r = item.json;

  const ingredients = r.ingredients
    .map(i => `${i.name}: ${i.amount}`)
    .join(", ");

  const instructions = r.instructions
    .map((step, index) => `${index + 1}. ${step}`)
    .join(" ");

  const chunks = [
    `${r.name}. ${r.description} Kategori: ${r.category}. Ingredienser: ${ingredients}.`,
    `${r.name}. Tilberedning: ${instructions}`
  ];

  chunks.forEach((text, index) => {
    output.push({
      json: {
        ...r,
        chunkIndex: index,
        chunkId: `${r.name.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-${index}`,
        text
      }
    });
  });
}

return output;

